(window.GROUP_QUIZZES=window.GROUP_QUIZZES||{})["clinical-medicine-and-surgery-i-exam-2-acute-vision-loss-vignettes"]={"title":"Acute Vision Loss Vignettes 1 — CMS I Exam 2","category":"Clinical Medicine and Surgery I","exam":"Exam 2","sem":"fall-2026","questions":[{"q":"A 38-year-old woman with papilledema is taking large doses of a supplement. Which does the lecture list as a cause?","choices":["Vitamin D toxicity","Vitamin A toxicity","Vitamin C excess","Iron deficiency"],"answer":1,"exp":"Correct, listed with tumour, trauma, intracranial infection and haemorrhage. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 43"},{"q":"A 26-year-old woman is diagnosed with optic neuritis. Which patient profile does the lecture describe for this condition?","choices":["Aged over 60 and mostly male","Children under 10","Aged 40 to 60 and mostly male","Aged 18 to 45 and mostly female"],"answer":3,"exp":"Correct; about 75% are women. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 23"},{"q":"A 69-year-old woman keeps bumping into door frames on her left. She has noticed nothing wrong with her reading vision and has no pain. Both intraocular pressures are 27 mmHg. Which is the most likely diagnosis?","choices":["Papilledema","Chronic open-angle glaucoma","Optic neuritis","Retinal detachment"],"answer":1,"exp":"Correct; peripheral field goes first while central vision is preserved. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 16"},{"q":"A 69-year-old man has sudden painless monocular vision loss and no other findings. Which single step does the lecture treat as non-negotiable?","choices":["Urgent ophthalmology involvement","A trial of topical antibiotics","Reassurance and review in a week","Repeat visual acuity in the morning"],"answer":0,"exp":"Correct; each of these diagnoses is sight-threatening and time-dependent. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 30"},{"q":"A 78-year-old woman has arteritic anterior ischemic optic neuropathy. Her inflammatory markers are markedly raised. What is done first?","choices":["Aspirin and clopidogrel","Intravenous methylprednisolone","Await the temporal artery biopsy result","Topical timolol"],"answer":1,"exp":"Correct, three days, then a slow oral taper; early therapy is critical. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 51"},{"q":"A 59-year-old woman with a history of anterior uveitis is started on a new inhaler and later develops a painful red eye. Which class does the lecture flag as a risk factor?","choices":["Nebulized bronchodilators","Beta-blocker eye drops","Prostaglandin analogues","Calcium channel blockers"],"answer":0,"exp":"Correct, listed alongside systemic anticholinergics such as atropine. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 14"},{"q":"A 69-year-old man has amaurosis fugax and you want to reduce his stroke risk. Which therapy does the lecture name?","choices":["Pilocarpine drops","Aspirin and clopidogrel","Oral acetazolamide","High-dose vitamin A"],"answer":1,"exp":"Correct, given to reduce cerebrovascular accident risk. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 8"},{"q":"A 29-year-old woman has had blurred vision in her left eye worsening over three days, and it hurts when she moves the eye. Colours look washed out. The disc appears normal. Which is the most likely diagnosis?","choices":["Angle-closure glaucoma","Papilledema","Retinal detachment","Optic neuritis"],"answer":3,"exp":"Correct. Painful eye movement, colour desaturation and an often normal disc. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 23"},{"q":"A 70-year-old man has painful acute vision loss. Which diagnosis does the pain point toward?","choices":["Central retinal artery occlusion","Retinal detachment","Amaurosis fugax","Acute angle-closure glaucoma"],"answer":3,"exp":"Correct; the occlusions and detachment are painless. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 33"},{"q":"A 54-year-old man has suspected non-arteritic anterior ischemic optic neuropathy. How does the lecture describe the workup?","choices":["Identical to the arteritic form","No workup is needed","Temporal artery biopsy only","Lumbar puncture first"],"answer":0,"exp":"Correct; it is a diagnosis of exclusion once arteritis is ruled out. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 52"},{"q":"A 63-year-old man's transient monocular vision loss is traced to a carotid embolus with significant plaque. Which intervention does the lecture pair with that finding?","choices":["Laser peripheral iridotomy","Intravenous methylprednisolone","Carotid endarterectomy","Calcium channel blockers"],"answer":2,"exp":"Correct. Calcium channel blockers are reserved for vascular spasm. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 8"},{"q":"A 72-year-old man with atrial fibrillation has profound painless loss of vision in the right eye that came on over a few seconds. He can only count fingers. The retina is pale and swollen with a cherry-red spot at the fovea. Which is the most likely diagnosis?","choices":["Retinal detachment","Central retinal artery occlusion","Central retinal vein occlusion","Amaurosis fugax"],"answer":1,"exp":"Correct. Sudden profound loss with the cherry-red fovea. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 39"},{"q":"A 64-year-old man is admitted with an intractable headache localised behind one eye. Multiple clinicians have treated him for migraine. On examination his eye is red and his vision is reduced. Which diagnosis should be excluded?","choices":["Papilledema","Optic neuritis","Retinal detachment","Angle-closure glaucoma"],"answer":3,"exp":"Correct. The lecture gave this exact case as a missed presentation. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 16"},{"q":"A 59-year-old man needs repair of a retinal detachment. Which does the lecture list as an option?","choices":["Temporal artery biopsy","Anterior chamber paracentesis","Scleral buckle","Peripheral iridotomy"],"answer":2,"exp":"Correct, with vitrectomy, pneumatic retinopexy, cryotherapy and laser photocoagulation. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 30"},{"q":"A 28-year-old woman has had a headache worst on waking for six weeks, with brief greying of vision when she stands. Both discs are elevated with engorged veins. Which is the most likely diagnosis?","choices":["Central retinal vein occlusion","Papilledema","Optic neuritis","Chronic open-angle glaucoma"],"answer":1,"exp":"Correct; bilateral disc swelling with the symptoms of raised intracranial pressure. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 44"},{"q":"A 67-year-old woman with amaurosis fugax asks what happens next. What does the lecture give as the outlook?","choices":["About half lose vision permanently","Recovery depends on surgery","The second eye is always affected","About 85% recover fully"],"answer":3,"exp":"Correct, and the remainder progress to a central retinal artery occlusion. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 8"},{"q":"A 65-year-old woman with sickle cell disease describes brief episodes in which the lower half of the vision in one eye fogs over and then clears within a minute. Which is the most likely diagnosis?","choices":["Optic neuritis","Papilledema","Amaurosis fugax","Retinal detachment"],"answer":2,"exp":"Correct; sickle cell is a listed risk factor and the episodes are transient. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 5"},{"q":"A 72-year-old man has chronic open-angle glaucoma that continues to progress on maximal drops. Which does the lecture give next?","choices":["A stronger prostaglandin analogue","Observation alone","Systemic corticosteroids","Laser trabeculoplasty"],"answer":3,"exp":"Correct, used when the disease is refractory or advanced. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 21"},{"q":"A 41-year-old man is told he has papilledema. Which pressure is raised?","choices":["Intracranial pressure","Intraocular pressure","Central venous pressure","Arterial blood pressure"],"answer":0,"exp":"Correct; the lecturer drew a sharp line against intraocular pressure. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 43"},{"q":"A 79-year-old man has sudden vision loss in one eye. Which referral threshold does the lecture apply?","choices":["Referral only if markers are raised","Emergent referral for anyone over 50","Routine referral within a month","Referral only with a headache"],"answer":1,"exp":"Correct, any patient over 50 with sudden visual loss. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 51"},{"q":"A 64-year-old woman has a branch retinal vein occlusion. How does her management compare with the central form?","choices":["It requires high-dose steroids","It requires surgical reattachment","It is essentially the same","It requires laser iridotomy"],"answer":2,"exp":"Correct; the lecture said the only difference is where the clot sits. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 35"},{"q":"A 73-year-old man loses vision in one eye. Which finding separates arterial from venous retinal occlusion on fundoscopy?","choices":["Blurred disc margins in both eyes","A cherry-red spot rather than haemorrhages","Disc cupping rather than swelling","An elevated grey retina"],"answer":1,"exp":"Correct; the artery gives pallor with a cherry-red fovea. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 39"},{"q":"A 72-year-old woman says a dark cloud has settled over the upper part of her vision in one eye. She notices it shifts when she lies down. There is no pain and no headache. Which is the most likely diagnosis?","choices":["Retinal detachment","Papilledema","Central retinal artery occlusion","Optic neuritis"],"answer":0,"exp":"Correct; the detached retina floats, so the defect moves with head position. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 27"},{"q":"A 70-year-old man with a hypercoagulable disorder develops a central retinal vein occlusion. What has occurred?","choices":["The iris has closed the drainage angle","Intracranial pressure has risen","A thrombus has occluded the vein","An embolus has lodged in the artery"],"answer":2,"exp":"Correct, preventing the retina from draining. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 32"},{"q":"A 65-year-old woman undergoes dilated ophthalmoscopy for suspected detachment. Which appearance does the lecture describe?","choices":["A cherry-red spot at the fovea","A deeply cupped disc","An elevated disc with blurred margins","An elevated grey area with folds"],"answer":3,"exp":"Correct, well demarcated and pigmented, with orange crescent-shaped tears. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 29"},{"q":"A 27-year-old woman has optic neuritis. Which imaging does the lecture specify?","choices":["MRI of brain and orbits, with and without contrast","Orbital ultrasound","Carotid Doppler","Fluorescein angiography"],"answer":0,"exp":"Correct, looking for demyelinating lesions. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 24"},{"q":"A 63-year-old myopic man reports a shower of floaters and flashing lights three days ago. Since yesterday a dark shadow has spread across the outer half of his vision. There is no pain. Which is the most likely diagnosis?","choices":["Optic neuritis","Angle-closure glaucoma","Retinal detachment","Amaurosis fugax"],"answer":2,"exp":"Correct. Flashes and floaters from the tear, then an advancing field defect. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 27"},{"q":"A 63-year-old man with hypertension and diabetes has sudden painless loss of vision in one eye. Fundoscopy shows a swollen disc, dilated veins, cotton wool spots and haemorrhages across all four quadrants. Which is the most likely diagnosis?","choices":["Central retinal vein occlusion","Central retinal artery occlusion","Papilledema","Optic neuritis"],"answer":0,"exp":"Correct. The blood and thunder fundus with disc swelling. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 34"},{"q":"A 66-year-old man presents six hours after a central retinal artery occlusion. Which option remains available per the lecture?","choices":["Oral prednisone taper","Carotid endarterectomy that evening","Thrombolytic infusion into the ophthalmic artery","Scleral buckle"],"answer":2,"exp":"Correct, within eight hours of onset. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 40"},{"q":"A 70-year-old woman has chronic open-angle glaucoma. Which abnormality does the lecture describe?","choices":["Trabecular meshwork change with aging","The iris obstructing the drainage angle","A thrombus in the central retinal vein","Optic nerve demyelination"],"answer":0,"exp":"Correct, next to the canal of Schlemm, damaging the optic nerve. — 12. Acute Vision Loss current - Jaquith.pptx, Slide 15"}]};
